import type { BigNumberTrendColors } from '../types';

export const DEFAULT_BIG_NUMBER_TREND_COLORS: BigNumberTrendColors = {
  positive: '#007800',
  negative: '#B91C1C',
};

const DEFAULT_DISPLAY_COLOR = '#141414';

type TrendDisplaySource = {
  trend?: 'positive' | 'negative';
  color?: string;
};

export const getTrendDisplayColor = (
  source?: TrendDisplaySource,
  trendColors: BigNumberTrendColors = DEFAULT_BIG_NUMBER_TREND_COLORS,
): string => {
  if (source?.trend) {
    return trendColors[source.trend];
  }
  return source?.color || DEFAULT_DISPLAY_COLOR;
};
